<?php
require_once '../includes/auth.php'; require_once '../includes/db.php'; require_once '../includes/staff_helper.php'; require_admin_user(); ensure_staff_table($conn); $user_id=(int)$_SESSION['user_id']; $id=(int)($_GET['id']??0);
$stmt=mysqli_prepare($conn,"SELECT * FROM staff WHERE id=? AND user_id=?"); mysqli_stmt_bind_param($stmt,'ii',$id,$user_id); mysqli_stmt_execute($stmt); $staff=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if(!$staff){ die('Staff record not found.'); } $has_transactions=staff_has_transactions($conn,$id);
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=$has_transactions ? $staff['name'] : trim($_POST['name']??''); $phone=trim($_POST['phone']??''); $address=trim($_POST['address']??''); $designation=staff_submitted_designation(); $stmt=mysqli_prepare($conn,"UPDATE staff SET name=?,phone=?,address=?,designation=? WHERE id=? AND user_id=?"); mysqli_stmt_bind_param($stmt,'ssssii',$name,$phone,$address,$designation,$id,$user_id); mysqli_stmt_execute($stmt); header('Location:index.php'); exit; }
$designations=staff_designations($conn,$user_id);
require_once '../includes/header.php'; require_once '../includes/navbar.php'; require_once '../includes/sidebar.php'; ?><div class="card"><div class="card-header"><h3 class="card-title">Edit Staff</h3></div><div class="card-body"><?php if($has_transactions){ ?><div class="alert alert-info">This staff has transactions, so the name cannot be changed.</div><?php } ?><form method="post"><div class="form-group"><label>Name</label><input class="form-control" name="name" value="<?=htmlspecialchars($staff['name'])?>" required <?=$has_transactions ? 'readonly' : ''?>></div><div class="form-group"><label>Phone</label><input class="form-control" name="phone" value="<?=htmlspecialchars($staff['phone'])?>"></div><div class="form-group"><label>Address</label><textarea class="form-control" name="address" rows="3"><?=htmlspecialchars($staff['address'] ?? '')?></textarea></div><div class="form-group"><label>Designation</label><select class="form-control" name="designation" id="designation"><option value="">Select Designation</option><?php foreach($designations as $item){ ?><option value="<?=htmlspecialchars($item)?>" <?=($staff['designation']??'')===$item?'selected':''?>><?=htmlspecialchars($item)?></option><?php } ?><option value="__new__">+ Add New Designation</option></select><input class="form-control mt-2" name="new_designation" id="new_designation" placeholder="Enter new designation" style="display:none;"></div><button class="btn btn-primary">Update Staff</button></form></div></div><script>document.getElementById('designation').addEventListener('change',function(){document.getElementById('new_designation').style.display=this.value==='__new__'?'block':'none';});</script><?php require_once '../includes/footer.php'; ?>
